def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, starting with the coefficient of the highest degree term.
    :return: The string representation of the polynomial.
    """
    from typing import List
    if not coeffs:
        return "0"

    terms = []
    for degree in range(n, -1, -1):
        coeff = coeffs[n - degree]
        if coeff == 0:
            continue

        # Determine the sign
        if degree == n and not terms:
            # First term: handle negative sign
            if coeff < 0:
                sign = "-"
                abs_coeff = -coeff
            else:
                sign = ""
                abs_coeff = coeff
        else:
            # Subsequent terms
            if coeff < 0:
                sign = "-"
                abs_coeff = -coeff
            else:
                sign = "+"
                abs_coeff = coeff

        # Determine the coefficient part
        if coeff == 1 or coeff == -1:
            if degree > 0:
                coeff_part = ""
            else:
                coeff_part = "1"
        else:
            coeff_part = str(abs(coeff))

        # Determine the variable part
        if degree == 0:
            var_part = ""
        elif degree == 1:
            var_part = "x"
        else:
            var_part = f"x^{degree}"

        term = sign + coeff_part + var_part
        terms.append(term)

    if not terms:
        return "0"

    return "".join(terms)

